import { test } from "node:test";
import assert from "node:assert/strict";
import { catalogHandlers, type ApiRequest, type Track } from "../src/catalog/tracks.ts";
import { upgradePinnedVersion, type Account } from "../src/catalog/accounts.ts";
import { LATEST_VERSION, renderTrack } from "../src/catalog/versions.ts";

const tracks: Track[] = [
    { id: "t1", title: "Night Drive", artists: [{ id: "a1", name: "Kaia" }, { id: "a2", name: "Mo Reyes" }], contentRating: "clean", durationMs: 214_000 },
    { id: "t2", title: "Static", artists: [{ id: "a3", name: "Halden" }], contentRating: "explicit", durationMs: 187_500 },
];

function setup() {
    const api = catalogHandlers({
        track: async (id) => structuredClone(tracks.find((t) => t.id === id) ?? null),
        playlist: async (id) => (id === "p1" ? { id, name: "Late commute", trackIds: ["t1", "gone", "t2"] } : null),
    });
    const req = (params: Record<string, string>, pinnedVersion: string, header?: string): ApiRequest => ({
        params,
        headers: { "tunes-version": header },
        account: { id: "partner-1", pinnedVersion },
    });
    return { api, req };
}

test("clients on the latest version get the current shape", async () => {
    const { api, req } = setup();
    const res = await api.getTrack(req({ id: "t1" }, LATEST_VERSION));
    assert.equal(res.headers["Tunes-Version"], "2026-02-01");
    assert.deepEqual(res.body, tracks[0]);
});

test("a client pinned to 2025-03-01 gets one artistName string and the explicit flag", async () => {
    const { api, req } = setup();
    const res = await api.getTrack(req({ id: "t2" }, "2025-03-01"));
    assert.deepEqual(res.body, { id: "t2", title: "Static", artistName: "Halden", explicit: true, durationMs: 187_500 });
});

test("a client pinned to the original 2024 version still gets an artist field", async () => {
    const { api, req } = setup();
    const res = await api.getTrack(req({ id: "t1" }, "2024-01-10"));
    console.log("track as served to a 2024-01-10 client:", res.body);
    assert.deepEqual(res.body, { id: "t1", title: "Night Drive", artist: "Kaia, Mo Reyes", explicit: false, durationMs: 214_000 });
});

test("playlists embed their tracks in the playlist's version", async () => {
    const { api, req } = setup();
    const res = await api.getPlaylist(req({ id: "p1" }, "2024-01-10"));
    const body = res.body as { totalDurationMs: number; tracks: Record<string, unknown>[] };
    assert.equal(body.totalDurationMs, 401_500);
    assert.deepEqual(body.tracks.map((t) => [t.artist, t.explicit]), [["Kaia, Mo Reyes", false], ["Halden", true]]);
});

test("the Tunes-Version header overrides the pinned version, and unknown versions get a 400", async () => {
    const { api, req } = setup();
    const res = await api.getTrack(req({ id: "t2" }, "2025-03-01", "2025-09-15"));
    assert.equal(res.headers["Tunes-Version"], "2025-09-15");
    assert.deepEqual(res.body, { id: "t2", title: "Static", artists: [{ id: "a3", name: "Halden" }], explicit: true, durationMs: 187_500 });
    const bad = await api.getTrack(req({ id: "t2" }, LATEST_VERSION, "2025-06-01"));
    assert.equal(bad.status, 400);
    assert.match((bad.body as { error: string }).error, /supported: 2024-01-10, 2025-03-01, 2025-09-15, 2026-02-01/);
});

test("rendering for an old version doesn't change the stored track", () => {
    const stored = structuredClone(tracks[1]);
    renderTrack(stored as unknown as Record<string, unknown>, "2024-01-10");
    assert.deepEqual(stored, tracks[1]);
});

test("upgrading a pinned version lists the changes being accepted and never goes backwards", async () => {
    const accounts = new Map<string, Account>([["partner-1", { id: "partner-1", pinnedVersion: "2024-01-10" }]]);
    const store = { get: async (id: string) => accounts.get(id) ?? null, save: async (a: Account) => void accounts.set(a.id, a) };
    const up = await upgradePinnedVersion(store, "partner-1", "2025-09-15");
    assert.deepEqual(up.ok && up.changes, [
        "2025-03-01: artist renamed to artistName",
        "2025-09-15: artistName replaced by artists: [{ id, name }] for collaborations",
    ]);
    assert.equal(accounts.get("partner-1")?.pinnedVersion, "2025-09-15");
    assert.deepEqual(await upgradePinnedVersion(store, "partner-1", "2025-03-01"), { ok: false, error: "Pinned versions can't be downgraded" });
});
